@page "/settings"
@using sv_53b20adac05f42c0a19d51dc6bca3c4e.Components.Pages.Settings
@using sv_53b20adac05f42c0a19d51dc6bca3c4e.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

/* Settings Layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    font-weight: 500;
    color: #495057;
    border-left: 3px solid transparent;
    transition: all 0.2s;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-small {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast.success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 4px;
    border: 1px solid #badbcc;
}

/* Toggle Labels */
.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0;
    cursor: pointer;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.avatar-url {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Channels Section */
.channels-section {
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.channels-section h3 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
}

/* Expandable Panel */
.expandable-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
}

.panel-header {
    width: 100%;
    text-align: left;
    background: #f8f9fa;
    border: none;
    padding: 0.75rem 1rem;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Two Factor */
.two-factor-section {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    border-radius: 10px;
    margin-left: 0.5rem;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

.info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-section h3 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #dee2e6;
    text-align: left;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

.current-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    background: #cfe2ff;
    color: #084298;
    border-radius: 10px;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.modal-dialog h3 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Error Message */
.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
}

/* Appearance Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 2px dashed #dee2e6;
    border-radius: 8px;
    transition: all 0.3s;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
    color: #6c757d;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.preview-content {
    padding: 1rem;
    border-radius: 4px;
    background: white;
    border: 1px solid #e9ecef;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: white;
    cursor: pointer;
}

.preview-meta {
    margin-top: 0.75rem;
    font-size: 0.8rem;
    color: #6c757d;
}

/* Theme Variations for Preview */
.preview-area.theme-dark {
    background: #1a1a2e;
    border-color: #444;
}

.preview-area.theme-dark .preview-header {
    color: #adb5bd;
}

.preview-area.theme-dark .preview-content {
    background: #16213e;
    border-color: #333;
    color: #e9ecef;
}

.preview-area.theme-dark .preview-text {
    color: #dee2e6;
}

.preview-area.theme-dark .preview-meta {
    color: #adb5bd;
}

/* Font Size Variations for Preview */
.preview-area.font-small .preview-content {
    font-size: 0.8rem;
}

.preview-area.font-medium .preview-content {
    font-size: 1rem;
}

.preview-area.font-large .preview-content {
    font-size: 1.2rem;
}

/* Compact Mode for Preview */
.preview-area.compact .preview-content {
    padding: 0.5rem;
    line-height: 1.2;
}

.preview-area.compact .preview-content p {
    margin-bottom: 0.35rem;
}

